#!/usr/bin/env python3
"""Build an offline reference library from measured UIKit snapshots; no app resources change."""
from pathlib import Path
import json, shutil, html, re
from PIL import Image
base=Path(__file__).resolve().parents[1]
repo=base.parents[1]
raw=Path('/tmp/native-typography-library')
scenes=json.loads((raw/'scenes.json').read_text())
# Modal examples document foreground content, not already catalogued navigation behind it.
for scene in scenes:
    if scene['category']=='Modal':
        scene['texts']=[t for t in scene['texts'] if 'JimiV9NavigationHeader[' not in t.get('path','')]

for scene in scenes:
    file=raw/(scene['id']+'.png')
    Image.open(file).convert('RGB').save(base/'screens'/(scene['id']+'.webp'),format='WEBP',quality=95,method=6)
for file in (repo/'assets/fonts').glob('Baloo2-*.ttf'):shutil.copy2(file,base/'fonts'/file.name)
for scene in scenes:
    source=repo/scene['source']
    lines=source.read_text().splitlines() if source.exists() else []
    for i,item in enumerate(scene['texts']):
        item['reference']='STS-'+scene['id'].upper()+'-'+str(int(item['id'].rsplit('-text-',1)[1])).zfill(2)
        text=item['text'];size=item['size'];button=item.get('button')
        if button:
            button['kind']='CTA' if button.get('kind')=='CTA' or item['color']=='gradient / pattern' or button.get('identifier') in ['native.end-run.exit','native.result.exit'] else 'Control'
        item['role']='CTA' if button and button.get('kind')=='CTA' else 'Naslov' if size>=28 else 'Podnaslov' if size>=18 else 'Opis / pomoćni tekst'
        if (text in ['Journey','Arcade','Forest','Beach','Area 55','Settings','Backpack']):item['role']='Navigacijski naslov'
        if scene['id']=='backpack' and text=='Forest':item['role']='Naslov sekcije'
        if scene['category']=='Modal' and text=='Backpack':item['role']='Naslov modala'
        if text in ['High score','Longest combo','Your score'] or text.startswith('Unlocked '):item['role']='Podnaslov / labela'
        if text.startswith('Stage ') and size>=28:item['role']='Naslov modala'
        if re.fullmatch(r'[+\d., /]+',text):item['role']='Broj / statistika'
        if text=='TAP TO COLLECT':item['role']='Uputa / interakcija'
        search=text if len(text)<80 else text[:30]
        match=next((n for n,line in enumerate(lines,1) if search in line and len(search)>2),None)
        if not match and text.startswith('Stage '):match=next((n for n,line in enumerate(lines,1) if 'Stage %02d' in line),None)
        if not match:match=next((n for n,line in enumerate(lines,1) if ('font' in line and str(int(size)) in line)),1)
        chosen=item.get('sourceHint',scene['source']);marker=None
        if text in ['Journey','Arcade']:chosen='native/jimi-2026/JimiV9HubView.swift';marker='title.text = arcade'
        elif text in ['Forest','Beach','Area 55'] and scene['id']!='backpack':chosen='native/jimi-2026/JimiNativeWorldView.swift';marker='title.font ='
        elif scene['id']=='settings' and text=='Settings':marker='title.text = "Settings"'
        elif scene['id']=='backpack' and text=='Backpack':marker='self.title.text=title'
        elif scene['id']=='backpack' and text=='Forest':marker='func apply(title:String'
        elif scene['id'].startswith('dice-detail'):marker='heading.font=assets.font(size:32' if size>=28 else 'copy.attributedText='
        elif scene['id'].startswith('stage'):
            if text.startswith('Stage '):marker='title.text = String(format:'
            elif text in ['High score','Longest combo']:marker='let label = UILabel('
            elif text.isdigit():marker='value.font=value.font.withSize' if size<32 else 'let value = UILabel('
        elif scene['id'].startswith('result'):
            if item.get('identifier')=='native.result.score':marker='(scoreLabel,20,'
            elif item.get('identifier')=='native.result.status':marker='status.text='
            elif text in ['Your score','NEW Highscore']:marker='scoreLabel.text="Your score"'
            elif size>=40:marker='let values:[(UILabel'
        elif scene['id']=='backpack-info' and text=='Backpack':marker='heading.font=assets.font(size:28'
        if marker:
            source_lines=(repo/chosen).read_text().splitlines()
            match=next((n for n,line in enumerate(source_lines,1) if marker in line),None)
        item['source']=chosen;item['sourceLine']=match or 1
        if button and button.get('kind')=='CTA':
            item['fontSource']='native/jimi-2026/JimiV9HomeView.swift'
            item['fontSourceLine']=next((n for n,line in enumerate((repo/item['fontSource']).read_text().splitlines(),1) if 'titleLabel?.font=artwork.font(size:28' in line),152)
        if item['color']=='gradient / pattern':
            item['colorDescription']='Ivory gradient · #FFFCED → #FFF6E1 → #F7E8CE'
        else:item['colorDescription']=item['color']
        # UILabel.textColor returns the first attributed accent for these mixed headings.
        # Resolve unstyled suffix runs from the explicit authored heading palette in Swift.
        if scene['id'].startswith('dice-detail') and size>=28 and ' ' in text:
            first=text.split(' ',1)[0]
            for run in item.get('runs',[]):
                run['color']='#E8744A' if run['text'].strip()==first else '#AD8675'
            item['colorResolution']='Mixed heading suffix fallback resolved from NativeBackpackDetail NativeBackpackCellPalette.ink; first-word accent is authored #E8744A.'
        distinct={(r['font'],r['size'],r['color']) for r in item.get('runs',[])}
        if len(distinct)>1:
            item['colorDescription']=' · '.join(r['text'].strip()+': '+r['color'] for r in item['runs'])
        if button and button.get('kind')=='CTA':
            item['surfaceColor']='#EE8158' if item['color']=='gradient / pattern' or item['color']=='#FFF6E1' else '#FFFFFF' if button['identifier'] in ['native.end-run.exit','native.result.exit'] else None
    scene['screenshot']='screens/'+scene['id']+'.webp'
(base/'data.json').write_text(json.dumps(scenes,indent=2,ensure_ascii=False)+'\n')
json_data=json.dumps(scenes,ensure_ascii=False).replace('</','<\\/')
